#include <iostream>

// Generic function template for min
template <typename T>
T myMin(T a, T b) {
    return (a < b) ? a : b;
}

// Generic function template for max
template <typename T>
T myMax(T a, T b) {
    return (a > b) ? a : b;
}

int main() {
    int i1 = 15, i2 = 42;
    char c1 = 'z', c2 = 'a';
    double d1 = 3.1415, d2 = 2.7182;

    std::cout << "myMin(15, 42) = " << myMin(i1, i2) << "\n";
    std::cout << "myMax(15, 42) = " << myMax(i1, i2) << "\n";
    std::cout << "myMin('z', 'a') = " << myMin(c1, c2) << "\n";
    std::cout << "myMax('z', 'a') = " << myMax(c1, c2) << "\n";
    std::cout << "myMin(3.1415, 2.7182) = " << myMin(d1, d2) << "\n";
    std::cout << "myMax(3.1415, 2.7182) = " << myMax(d1, d2) << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <stdexcept>

int main() {
    // Create a vector of 5 integers, default initialized to 0
    std::vector<int> numbers(5);
    for (size_t i = 0; i < numbers.size(); ++i) {
        numbers[i] = static_cast<int>((i + 1) * 10);
    }

    std::cout << "Vector size: " << numbers.size() << "\n";
    std::cout << "Elements: ";
    for (int val : numbers) {
        std::cout << val << " ";
    }
    std::cout << "\n";

    // Test exception handling with bounds-checked .at()
    try {
        std::cout << "Accessing valid index 2: " << numbers.at(2) << "\n";
        std::cout << "Attempting out-of-range index 10...\n";
        int invalid = numbers.at(10); // Throws std::out_of_range
        std::cout << "Value: " << invalid << "\n";
    } catch (const std::out_of_range& ex) {
        std::cout << "Caught std::out_of_range exception successfully!\n";
    }

    return 0;
}
